// @ui:core loom
// @ui:provides init controllers

// Auto-init all recipe controllers found in the DOM.
// This file is regenerated by `loom add` when recipes are installed.

import { createDialog } from "../recipes/dialog/dialog.js";
import { createTable } from "../recipes/table/table.js";
import { createDatePicker } from "../recipes/date-picker/date-picker.js";

const controllers = {
  dialog: createDialog,
  table: createTable,
  "date-picker": createDatePicker,
};

export function initAll(root = document) {
  for (const [name, create] of Object.entries(controllers)) {
    for (const el of root.querySelectorAll(`[data-ui="${name}"]`)) create(el);
  }
}

if (typeof document !== "undefined") {
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => initAll());
  } else {
    initAll();
  }
}
